mapper.select:
select
,
,
(select count(1) from pci_api_endpoint endpoint  WHERE endpoint.api_account=pci_api_account.id) as apiEndpointCount
from pci_api_account


    AND name = #{record.name,jdbcType=VARCHAR}


    AND system_type = #{record.systemType,jdbcType=VARCHAR}


    AND provider_factory_id = #{record.providerFactoryId,jdbcType=VARCHAR}


    AND status = #{record.status,jdbcType=VARCHAR}


    AND api_endpoint = #{record.apiEndpoint,jdbcType=VARCHAR}


    AND test_api_endpoint = #{record.testApiEndpoint,jdbcType=VARCHAR}


    AND version = #{record.version,jdbcType=VARCHAR}


    AND enable_flag = #{record.enableFlag,jdbcType=VARCHAR}


    AND sync_status = #{record.syncStatus,jdbcType=VARCHAR}


    AND auto_sync = #{record.autoSync,jdbcType=BIT}

select pae.id, pae.api_type, pae.api_account, pae.endpoint, pae.method, pae.update_time,
       paa.name as accountName, paa.api_endpoint, paa.system_type, pae.request_template  as requestTemplate,paa.provider_factory_id as providerFactoryId,
       pae.custom_content as customContent,
       (select count(1) from pci_api_parameter_mapping mapping  WHERE mapping.api_id=pae.id) as parameterMappingCount
from pci_api_endpoint pae inner join pci_api_account paa
on pae.api_account = paa.id


    AND pae.id = #{record.id,jdbcType=VARCHAR}


    AND paa.system_type = #{record.systemType,jdbcType=VARCHAR}


    AND pae.api_type = #{record.apiType,jdbcType=VARCHAR}


    AND pae.api_account = #{record.apiAccount,jdbcType=VARCHAR}


    AND pae.endpoint like #{record.endpoint,jdbcType=VARCHAR}


    AND pae.method = #{record.method,jdbcType=VARCHAR}


    AND pae.update_time = #{record.updateTime,jdbcType=TIMESTAMP}

select mapping.id, mapping.api_id, mapping.origin_field,mapping.origin_field_name, mapping.origin_field_type, mapping.target_field, mapping.target_field_type,
mapping.update_time,mapping.description,mapping.origin_field_source,mapping.origin_field_table,mapping.field_tag,endpoint.endpoint,endpoint.api_type,account.provider_factory_id
from pci_api_parameter_mapping as mapping
left join pci_api_endpoint as endpoint on mapping.api_id=endpoint.id
left join pci_api_account as account on endpoint.api_account=account.id


    AND mapping.id = #{record.id,jdbcType=VARCHAR}


    AND mapping.api_id = #{record.apiId,jdbcType=VARCHAR}


    AND (mapping.origin_field like #{record.originField,jdbcType=VARCHAR}
        or mapping.origin_field_name like #{record.originField,jdbcType=VARCHAR})


    AND mapping.origin_field_type = #{record.originFieldType,jdbcType=VARCHAR}


    AND mapping.target_field like #{record.targetField,jdbcType=VARCHAR}


    AND mapping.target_field_type = #{record.targetFieldType,jdbcType=VARCHAR}


    AND mapping.description like #{description,jdbcType=LONGVARCHAR}


    AND mapping.origin_field_source = #{originFieldSource,jdbcType=LONGVARCHAR}


    AND mapping.origin_field_table = #{originFieldTable,jdbcType=LONGVARCHAR}


    AND mapping.field_tag like  #{record.fieldTag,jdbcType=VARCHAR}

select

from pci_api_account


    AND name = #{record.name,jdbcType=VARCHAR}


    AND system_type = #{record.systemType,jdbcType=VARCHAR}


    AND provider_factory_id = #{record.providerFactoryId,jdbcType=VARCHAR}


    AND status = #{record.status,jdbcType=VARCHAR}


    AND api_endpoint = #{record.apiEndpoint,jdbcType=VARCHAR}


    AND test_api_endpoint = #{record.testApiEndpoint,jdbcType=VARCHAR}


    AND version = #{record.version,jdbcType=VARCHAR}

select id, api_type, api_account, endpoint, method, update_time, request_template, custom_content
from pci_api_endpoint
WHERE api_account = #{accountId};
